/**
 * Populates the notes array with 525 unique, human-sounding seed notes across the 5 core categories:
 * 'morning', 'vle_fatigue', 'field_work', 'late_night', 'comfort'.
 * Also updates the Zustand store while preserving any custom 'random_love' notes.
 */
export function generateSeedNotes() {
  try {
    const generatedNotes = [];
    let counter = 0;

    for (const [category, messages] of Object.entries(SEED_NOTES_BY_CATEGORY)) {
      for (const text of messages) {
        counter += 1;
        const safeId =
          typeof crypto !== 'undefined' &&
          typeof crypto.randomUUID === 'function'
            ? crypto.randomUUID()
            : `seed-${category}-${counter}`;
        generatedNotes.push({
          id: safeId,
          category,
          text,
        });
      }
    }

    const store = useStore.getState();
    const existingNotes = Array.isArray(store.notes) ? store.notes : [];
    const existingCustomNotes = existingNotes.filter(
      (note) => note && note.category === 'random_love'
    );

    const combinedNotes = [...generatedNotes, ...existingCustomNotes];
    if (typeof store.setNotes === 'function') {
      store.setNotes(combinedNotes);
    } else if (typeof store.seedInitialNotes === 'function') {
      store.seedInitialNotes(generatedNotes);
    }

    return combinedNotes;
  } catch {
    return [];
  }
}

/**
 * Takes a string of notes separated by newlines, assigns them to the 'random_love'
 * category, and appends them to the existing notes array in the Zustand store.
 * @param {string} rawText
 * @returns {Array<{ id: string, category: string, text: string }>}
 */
export function appendBulkNotes(rawText) {
  if (!rawText || typeof rawText !== 'string') return [];

  const lines = rawText
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);

  if (lines.length === 0) return [];

  const newNotes = lines.map((text) => ({
    id: crypto.randomUUID(),
    category: 'random_love',
    text,
  }));

  const store = useStore.getState();
  store.appendNotes(newNotes);

  return newNotes;
}

export default generateSeedNotes;
